:root {
  --card: #fffdf7;
  --ink: #243447;
  --accent: #2b7a78;
}

.umbrella-card {
  width: 460px;
  box-sizing: border-box;
  padding: 18px;
  background-color: var(--card);
  border: 2px solid var(--ink);
  border-radius: 18px;
  color: var(--ink);
}

.card-header {
  display: flex;
  align-items: center;
  gap: 12px;
}

.icon {
  font-size: 34px;
}

.eyebrow {
  margin: 0 0 3px;
  color: var(--accent);
  font-size: 11px;
  font-weight: 700;
}

.umbrella-card h1 {
  margin: 0;
  font-size: 22px;
  line-height: 1.1;
}

.location {
  margin: 16px 0 0;
  font-size: 14px;
}

.status {
  display: flex;
  justify-content: space-between;
  margin-top: 14px;
  padding-top: 10px;
  border-top: 1px solid var(--accent);
  color: var(--accent);
  font-size: 13px;
  font-weight: 700;
}
